NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Haggai'

CHAPTERS = {
    1: {
        1: 'V drugem letu kralja Dareja, v šestem mesecu, na prvi dan meseca, je prišla Gospodova beseda po preroku Ageju k Zerubabélu, Šealtiélovemu sinu, voditelju Juda in k Ješúu, Jocadákovemu sinu, vélikemu duhovniku, rekoč:',
        2: '»Tako govori Gospod nad bojevniki, rekoč: ›To ljudstvo pravi: ›Čas ni prišel, čas, da bi bila zgrajena Gospodova hiša.‹',
        3: 'Potem je prišla Gospodova beseda po preroku Ageju, rekoč:',
        4: '› Ali je čas za vas, oh vi, da prebivate v svojih obitih hišah, ta hiša pa leži zapuščena?‹',
        5: 'Zdaj torej tako govori Gospod nad bojevniki: ›Preudarite svoje poti.‹',
        6: 'Mnogo ste sejali, prinesli pa malo; jedli ste, toda nimate dovolj; pijete, toda niste nasičeni s pijačo; oblačite se, toda nihče ni ogret; in tisti, ki zasluži plačila, zasluži plačila, da jih daje v torbo z luknjami.‹',
        7: 'Tako govori Gospod nad bojevniki: ›Preudarite svoje poti.',
        8: 'Pojdite gor na goro, pripeljite les, zgradite hišo in razveseljeval se bom v njej in jaz bom proslavljen,‹ govori Gospod.',
        9: 'Precej ste iskali in glejte, postalo je malo; in ko ste to prinesli domov, sem pihnil na to. Zakaj?‹ govori Gospod nad bojevniki. ›Zaradi moje hiše, ki je opustošena, vi pa tečete vsakdo za svojo lastno hišo.',
        10: 'Zatorej je nebo nad vami zadržano pred roso in zemlja je zadržana pred njenim sadom.',
        11: 'In jaz sem poklical sušo na deželo, na gore, na žito, na novo vino, na olje in na to, kar prinašajo tla, na ljudi, na živino in na ves trud rok.‹«',
        12: 'Potem sta Zerubabél, Šealtiélov sin in Ješúa, Jocadákov sin, véliki duhovnik, z vsem preostankom ljudstva, ubogala glas Gospoda, svojega Boga in besede preroka Ageja, kakor mu jih je poslal Gospod, njihov Bog in ljudstvo se je balo pred Gospodom.',
        13: 'Potem je spregovoril Agej, Gospodov poslanec v Gospodovi poslanici ljudstvu, rekoč: ›Jaz sem z vami,‹ govori Gospod.',
        14: 'In Gospod je razvnel duha Zerubabéla, Šealtiélovega sina, voditelja Judeje in duha Ješúa, Jocadákovega sina, vélikega duhovnika in duha vsega preostanka ljudstva in prišli so in delali v hiši Gospoda nad bojevniki, svojega Boga,',
        15: 'v štiriindvajsetem dnevu šestega meseca, v drugem letu kralja Dareja.',
    },
    2: {
        1: 'V sedmem mesecu, na enaindvajseti dan meseca, je prišla Gospodova beseda po preroku Ageju, rekoč:',
        2: '»Govori sedaj Zerubabélu, Šealtiélovemu sinu, voditelju Judeje in Ješúu, Jocadákovemu sinu, vélikemu duhovniku in preostanku ljudstva, rekoč:',
        3: '›Kdo je preostal med vami, ki je to hišo videl v njeni prvi slavi? In kakšno jo vidite sedaj? Mar ni to v vaših očeh v primerjavi z njo kakor nič?',
        4: 'Vendar bodi sedaj močan, oh Zerubabél,‹ govori Gospod ›in bodi močan, oh Ješúa, Jocadákov sin, véliki duhovnik in bodi močno, vse ljudstvo dežele,‹ govori Gospod ›in delajte, kajti jaz sem z vami,‹ govori Gospod nad bojevniki.',
        5: 'Glede na besedo, s katero sem se zavezal z vami, ko ste prišli iz Egipta, tako moj duh ostaja med vami. Ne bojte se.‹',
        6: 'Kajti tako govori Gospod nad bojevniki: ›Še enkrat, to je kratek čas in stresel bom nebo, zemljo, morje in kopno zemljo',
        7: 'in stresel bom vse narode in želja vseh narodov bo prišla in to hišo bom napolnil s slavo,‹ govori Gospod nad bojevniki.',
        8: '›Moje je srebro in moje je zlato,‹ govori Gospod nad bojevniki.',
        9: '›Slava te poslednje hiše bo večja kakor prejšnje,‹ govori Gospod nad bojevniki, ›in na tem kraju bom dal mir,‹ govori Gospod nad bojevniki.«',
        10: 'Na štiriindvajseti dan devetega meseca, v drugem letu Dareja, je prišla Gospodova beseda po preroku Ageju, rekoč:',
        11: '»Tako govori Gospod nad bojevniki: ›Vprašaj torej duhovnike glede postave, rekoč:',
        12: '›Če nekdo nosi sveto meso v krajcu svoje obleke in se s krajcem svojega oblačila dotakne kruha ali juhe ali vina ali olja ali katerekoli hrane, ali bo ta postala sveta?‹« Duhovniki so odgovorili in rekli: »Ne.«',
        13: 'Potem je Agej rekel: »Če se nekdo, ki je nečist s truplom, dotakne karkoli od tega ali bo to nečisto?« Duhovniki so odgovorili in rekli: »To bo nečisto.«',
        14: 'Potem je Agej odgovoril in rekel: »Takšno je to ljudstvo in takšen je ta narod pred menoj,« govori Gospod, »in takšno je vsako delo njihovih rok; in to, kar tam darujejo, je nečisto.',
        15: 'In sedaj vas prosim, preudarite od tega dne in naprej, od preden je bil kamen položen na kamen v Gospodovem templju.',
        16: 'Odkar so bili tisti dnevi, ko je nekdo prišel h kupu dvajsetih mer, jih je bilo tam samo deset. Ko je nekdo prišel, da iz stiskalnice zajame petdeset posod, jih je bilo tam samo dvajset.',
        17: 'Udaril sem vas s kvarjenjem in s plesnijo in s točo v vseh naporih vaših rok, vendar se niste obrnili k meni,« govori Gospod.',
        18: 'Preudarite torej od tega dne in naprej, od štiriindvajsetega dne devetega meseca, celo od dneva, ko je bil položen temelj Gospodovega templja, preudarite to.',
        19: 'Je seme še v skednju? Da, do tega trenutka trta, figovo drevo, granatno jabolko in oljka še niso obrodili. Od tega dne vas bom blagoslavljal.«',
        20: 'Ponovno je prišla Gospodova beseda k Ageju, v štiriindvajsetem dnevu meseca, rekoč:',
        21: '»Govori Zerubabélu, voditelju Juda, rekoč: ›Stresel bom nebo in zemljo',
        22: 'in prevrnil bom prestol kraljestev in uničil bom moč poganskih kraljestev in prevrnil bom bojne vozove in tiste, ki se peljejo na njih, in konji in njihovi jezdeci bodo padli, vsak pod mečem svojega brata.',
        23: 'Na tisti dan,« govori Gospod nad bojevniki, »te bom vzel, oh Zerubabél, moj služabnik, Šealtiélov sin,« govori Gospod »in te naredil kakor pečat, kajti tebe sem izbral,« govori Gospod nad bojevniki.',
    },
}
